 *
 * @param hints a map of hints to locate the authority and object factories. (can be null)
 */
public GeoTiffMetadata2CRSAdapter(Hints hints) {

    this.hints = hints != null ? hints.clone() : GeoTools.getDefaultHints().clone();
    // Might alleviate a rare deadlock
    // https://osgeo-org.atlassian.net/browse/GEOT-5405
    this.hints.put(Hints.DEFAULT_COORDINATE_REFERENCE_SYSTEM, FeatureReader.DefaultCRS);
    this.hints.put(Hints.FORCE_LONGITUDE_FIRST_AXIS_ORDER, true);

    // various authority related factories
    allAuthoritiesFactory = new AllAuthoritiesFactory(this.hints);

    // various factories
    datumObjFactory = ReferencingFactoryFinder.getDatumFactory(this.hints);
    mtFactory = ReferencingFactoryFinder.getMathTransformFactory(this.hints);
}

/**
 * This method creates a <code>CoordinateReferenceSystem</code> object from the metadata which
 * has been set earlier. If it cannot create the <code>CoordinateReferenceSystem</code>, then
 * one of three exceptions is thrown to indicate the error.
 *
 * @param metadata  the metadata extracted from the GeoTIFF file
 * @return the <code>CoordinateReferenceSystem</code> object representing the file data
 * @throws IOException if there is unexpected data in the GeoKey tags.
 * @throws NullPointerException if the <code>csAuthorityFactory</code>, <code>datumFactory
 *     </code>, <code>crsFactory</code> or <code>metadata</code> are uninitialized
 * @throws UnsupportedOperationException if the coordinate system specified by the GeoTiff file
 *     is not supported.
 */
public CoordinateReferenceSystem createCoordinateSystem(
        final GeoTiffMetadata metadata) throws Exception {

