 * @param metadata the metadata instance to extract the information from.
 * @return an instance of the {@link PixelInCell} enum that capture the raster type.
 */
public static PixelInCell getRasterType(GeoTiffMetadata metadata) {
    int rasterType = getGeoKeyAsInt(GTRasterTypeGeoKey, metadata);

    // geotiff spec says that PixelIsArea is the default
    if (rasterType == UNDEFINED) {
        rasterType = RasterPixelIsArea;
    }
    if (rasterType == RasterPixelIsArea) {
        return PixelInCell.CELL_CORNER;
    } else if (rasterType == RasterPixelIsPoint) {
        return PixelInCell.CELL_CENTER;
    }
    throw new IllegalArgumentException("Unsupported rasterType");
}

/**
 * Getting a specified geotiff geo key as a double. It is somehow tolerant in the sense that in
 * case such a key does not exist it returns <code>Double.NaN</code>.
 *
 * @param key we want to get the value for.
 * @param metadata containing the key we are looking for.
 * @return the value for the provided key.
 */
private static double getGeoKeyAsDouble(
        final int key, final GeoTiffMetadata metadata) {

    try {
        final String geoKey = metadata.getGeoKey(key);
        if (geoKey != null) return Double.parseDouble(geoKey);
        else return Double.NaN;
    } catch (NumberFormatException ne) {
        if (LOGGER.isLoggable(Level.WARNING))
            LOGGER.log(Level.WARNING, ne.getLocalizedMessage(), ne);
        return Double.NaN;
    } catch (Exception e) {
        LOGGER.log(Level.WARNING, e.getLocalizedMessage(), e);
        return Double.NaN;
    }
}

